arguments.sql_query:
WITH endo_concepts AS (
  SELECT descendant_concept_id AS concept_id FROM omop.concept_ancestor WHERE ancestor_concept_id = 433527
  UNION SELECT 433527
), endo AS (
  SELECT person_id, MIN(condition_start_date) AS endo_date
  FROM omop.condition_occurrence
  WHERE condition_concept_id IN (SELECT concept_id FROM endo_concepts)
  GROUP BY person_id
)
SELECT COUNT(*) AS n_endometriosis_patients FROM endo;

WITH med_seed AS (
  SELECT v.concept_id FROM (VALUES (1511449),(19054876),(1560104),(1366310),(1351541),(1500211),(1507558),(1521369),(1343039)) v(concept_id)
), med_concepts AS (
  SELECT concept_id FROM med_seed
  UNION SELECT ca.descendant_concept_id FROM omop.concept_ancestor ca JOIN med_seed m ON ca.ancestor_concept_id=m.concept_id
)
SELECT COUNT(*) AS n_med_concepts FROM med_concepts;
